customCSS:
.t, .history { color: #727169; }
.join { color: #76946a; }
.part, .quit { color: #727169; }
.kick, .error { color: #c34043; }
.notice { color: #c0a36e; }
.action { color: #957fb8; }
.mode, .nick, .topic, .server { color: #6a9589; }
.highlight { color: #dcd7ba; background-color: #2d4f67; border-left: 3px solid #957fb8; padding-left: 8px; }
.reply { color: #727169; border-left: 2px solid #7e9cd8; padding-left: 6px; }
.oper { color: #1f1f28; background-color: #c0a36e; }
.reactions { color: #7e9cd8; background-color: #090618; }
.card { background-color: #090618; border-color: #727169; }
.card-title { color: #7e9cd8; }
.card-desc { color: #727169; }
.daychange { color: #727169; border-color: #090618; }
